from pathlib import Path
p=Path('packages/persistence/src/priority-national-source-coverage.ts')
s=p.read_text()
m='const CIPO: Authority = {'
assert m in s
b='''  target(MYIPO_MY, {\n    id: "my-myipo-trademark-law",\n    family: "LEGAL_TEXTS",\n    displayName: "Malaysia MyIPO Trademark Act, Regulations and Legal Materials",\n    canonicalUri: "https://www.myipo.gov.my/trademark-act/",\n    fetchAttachmentsHint: true,\n    expectedArtifactKinds: ["HTML", "MARKDOWN", "PDF"],\n    verificationEvidenceUri: "https://www.myipo.gov.my/trademark-act/",\n    notes: "MyIPO's primary legal-materials page publishes Act 815, Trademarks Regulations, orders, examination manual materials, practice directions and current guidelines.",\n  }),\n  target(MYIPO_MY, {\n    id: "my-myipo-trademark-guidelines-2026",\n    family: "EXAMINATION_MANUAL",\n    displayName: "Malaysia MyIPO Guidelines of Trademark 2019 VA1-2026",\n    canonicalUri: "https://www.myipo.gov.my/guidelines-of-trademark-2019-va1-2026/",\n    fetchAttachmentsHint: true,\n    expectedArtifactKinds: ["HTML", "PDF"],\n    verificationEvidenceUri: "https://www.myipo.gov.my/guidelines-of-trademark-2019-va1-2026/",\n    notes: "MyIPO publishes Guidelines of Trademark 2019 (VA1-2026), varied on 30 January 2026 and effective from 1 February 2026, as current trademark practice guidance.",\n  }),\n  target(MYIPO_MY, {\n    id: "my-myipo-trademark-proceedings",\n    family: "PROCEEDINGS",\n    displayName: "Malaysia MyIPO Trademark Management and Proceedings",\n    canonicalUri: "https://www.myipo.gov.my/managing-your-trademark/",\n    entrypoints: [\n      { uri: "https://www.myipo.gov.my/managing-your-trademark/", label: "Renewal, restoration and trademark management" },\n      { uri: "https://www.myipo.gov.my/trademark-act/", label: "Official hearing, appeal and opposition manual materials" },\n    ],\n    verificationEvidenceUri: "https://www.myipo.gov.my/managing-your-trademark/",\n    notes: "MyIPO's management surface covers renewal/restoration and related forms, while its official legal materials include examination-manual chapters for hearing, appeal and opposition proceedings.",\n  }),\n  target(MYIPO_MY, {\n    id: "my-myipo-trademark-journal",\n    family: "OFFICIAL_GAZETTE",\n    displayName: "Malaysia MyIPO Trademark Journal",\n    canonicalUri: "https://www.myipo.gov.my/trademark-journal/",\n    coverageTier: "CHANGE_SIGNAL",\n    fetchAttachmentsHint: true,\n    expectedArtifactKinds: ["HTML", "PDF"],\n    verificationEvidenceUri: "https://www.myipo.gov.my/trademark-journal/",\n    notes: "MyIPO continuously publishes numbered Trademark Journal issues, including weekly 2026 issues, making the journal a high-value publication and change-signal source.",\n  }),\n] satisfies readonly SourceCoverageTarget[];\n\n'''
s=s.replace(m,b+m,1)
old='  ...DOI_NP_SOURCE_COVERAGE_TARGETS,\n  ...CIPO_SOURCE_COVERAGE_TARGETS,'
assert old in s
s=s.replace(old,'  ...DOI_NP_SOURCE_COVERAGE_TARGETS,\n  ...MYIPO_MY_SOURCE_COVERAGE_TARGETS,\n  ...CIPO_SOURCE_COVERAGE_TARGETS,',1)
p.write_text(s)
